def facts():
    events = []
    keep_run, keep_free = R.execute, KD.KTPUAllocator._free

    def execute(dev, plan, bufs):
        events.append("run")
        return keep_run(dev, plan, bufs)

    def free(self, opaque, options):
        events.append("free")
        return keep_free(self, opaque, options)

    t = (T(X).relu() @ T(W).T).relu() @ T(W2).T
    R.execute, KD.KTPUAllocator._free = execute, free
    try:
        t.realize()
    finally:
        R.execute, KD.KTPUAllocator._free = keep_run, keep_free
    last = len(events) - 1 - events[::-1].index("run")
    return {"runs": events.count("run") >= 3, "freed_mid": "free" in events[:last]}
